"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
} from "react";


export type User = {
  id:number;
  name:string;
  email:string;
  role:string;
  avatar?:string | null;
  phone?:string | null;
  address?:string | null;
  memberSince?:string | null;
};



type AuthContextType = {

  user:User | null;

  login:
  (
    email:string,
    password:string
  )=>Promise<boolean>;

  logout:()=>Promise<void>;

  isLoggedIn:boolean;

};



const AuthContext =
createContext<AuthContextType|null>(null);





export function AuthProvider({
 children
}:{
 children:ReactNode;
}){


const [user,setUser] =
useState<User|null>(null);





useEffect(()=>{


const saved =
localStorage.getItem("user");


if(saved){

setUser(
JSON.parse(saved)
);

}


},[]);







async function login(
 email:string,
 password:string
){


console.log(
"LOGIN FUNCTION CALLED"
);



const res =
await fetch(
"/api/auth/login",
{

method:"POST",

credentials:"include",

headers:{
"Content-Type":"application/json"
},

body:JSON.stringify({

email,

password

})

}
);





const data =
await res.json();



console.log(
"LOGIN RESPONSE:",
data
);





if(!res.ok){

return false;

}





const loggedUser =
data.data.user;



localStorage.setItem(
"user",
JSON.stringify(loggedUser)
);



setUser(
loggedUser
);



return true;


}









async function logout(){


await fetch(
"/api/auth/logout",
{
method:"POST",
credentials:"include"
}
);



localStorage.removeItem(
"user"
);


setUser(null);


}








return (

<AuthContext.Provider

value={{

user,

login,

logout,

isLoggedIn:!!user

}}

>


{children}


</AuthContext.Provider>


);


}









export function useAuth(){


const context =
useContext(AuthContext);



if(!context){

throw new Error(
"useAuth must be used inside AuthProvider"
);

}


return context;


}